-- Run APPLY_00 then APPLY_01..4. Expect glossary +~1627 (1635 minus 8 pre-existing).
SELECT (SELECT count(*) FROM glossary) AS glossary_total;
SELECT a.name, count(*) terms FROM glossary_topics gt JOIN achievements a ON a.id=gt.achievement_id WHERE gt.is_primary AND a.id IN ('0c5fa38e-c585-429a-ae4a-298a1d47ffb5','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7','c6987d6b-2547-441b-8cd1-88847ade6bae','2193b2b3-b629-4127-a8b3-d71bf077ca3d','f9e9fa38-e692-44c0-92da-653529165c7c','3a0d6514-af65-43d9-abc4-f4e84efeaba2','03c488e9-47e6-4ec7-9aca-9d8aa42032a4','2ffa9e64-cdfc-46eb-886e-2158536093d8','601f6272-8859-47f6-a873-447c45f286ef','d64162b5-13a1-46cf-bb3d-a744183f036e','dd8b965c-5f45-4093-b6c3-4bef7412a57e','50228531-9071-46f7-b2bb-171a0af621e4','0f467b36-934f-42ea-ade7-4eb6007b74ca','a439fbe5-f3ef-4736-a20c-6c2ae3b42678','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546','b87c9747-1e25-4a6d-9345-aceeb9441312') GROUP BY a.name ORDER BY terms DESC;
SELECT count(*) multi_primary FROM (SELECT glossary_id FROM glossary_topics WHERE is_primary GROUP BY glossary_id HAVING count(*)>1) x;
